import {useQuery} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {ArrowUpRightIcon, SparkleFillIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, RelativeTime, Spinner, Truncate} from '@primer/react'
import {memo, useMemo} from 'react'

import {useWorkbenchContext} from '../contexts/WorkbenchContext'
import type {Workbench} from '../types/workbench-types'
import styles from './SparkSwitcher.module.css'

export const SparkSwitcher = memo(() => {
  const workbench = useWorkbenchContext()

  const {data: sparks, isLoading} = useQuery({
    queryKey: ['sparks'],
    queryFn: async () => {
      // Hits app/controllers/copilot/workbench_controller.rb#index
      const res = await verifiedFetchJSON('/copilot/spark/workbench', {method: 'GET'})
      if (!res.ok) throw new Error('Failed to fetch')
      const data = (await res.json()) as {workbenches: Workbench[]}
      return data.workbenches
    },
  })

  const recentSparks = useMemo(() => {
    if (!sparks) return []

    // shallow copy because sorting mutates the array in place
    return [...sparks]
      .filter(spark => spark.id !== workbench.id) // Exclude the current workbench
      .sort((a, b) => {
        if (!a.updatedAt) return 1
        if (!b.updatedAt) return -1
        return new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()
      })
      .slice(0, 5)
  }, [sparks, workbench])

  return (
    <ActionMenu>
      <ActionMenu.Button size="medium" variant="invisible" className={styles.switcher}>
        {/* 234px is the specific size we need to constrain it to in order for the header to align with the side panel */}
        <Truncate title={workbench.name} maxWidth="234px">
          {workbench.name}
        </Truncate>
      </ActionMenu.Button>
      {/* eslint-disable-next-line primer-react/no-system-props */}
      <ActionMenu.Overlay maxHeight="medium" width="small" maxWidth="medium" className={styles.sparkSwitcherOverlay}>
        <ActionList>
          {(isLoading || recentSparks.length > 0) && (
            <>
              <ActionList.Group>
                {isLoading ? (
                  <ActionList.Item disabled>
                    <ActionList.LeadingVisual>
                      <Spinner size="small" />
                    </ActionList.LeadingVisual>
                    Grabbing recent sparks…
                  </ActionList.Item>
                ) : (
                  recentSparks.map(spark => (
                    <ActionList.LinkItem
                      key={spark.id}
                      href={workbench.sparkBaseUrl(spark)}
                      target="_blank"
                      className={styles.sparkLink}
                    >
                      {spark.name}
                      {spark.updatedAt && (
                        <ActionList.Description variant="block">
                          Updated <RelativeTime date={new Date(spark.updatedAt)} />
                        </ActionList.Description>
                      )}
                      <ActionList.TrailingVisual>
                        <ArrowUpRightIcon aria-label="Opens in a new tab" />
                      </ActionList.TrailingVisual>
                    </ActionList.LinkItem>
                  ))
                )}
              </ActionList.Group>
              <ActionList.Divider />
            </>
          )}

          <ActionList.Group>
            <ActionList.LinkItem href="/spark" target="_blank">
              <ActionList.LeadingVisual>
                <SparkleFillIcon />
              </ActionList.LeadingVisual>
              All sparks
            </ActionList.LinkItem>
          </ActionList.Group>
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
})

SparkSwitcher.displayName = 'SparkSwitcher'
