import type {Iteration} from '../types/workbench-types'

export type DisplayItem = {type: 'refinement'; refinement: Iteration} | {type: 'skip'; skippedRefinements: Iteration[]}

export const buildDisplayRefinements = (activeRefinement: Iteration, allRefinements: Iteration[]): DisplayItem[] => {
  // Helper function to get the appropriate key for an iteration
  const getIterationKey = (iteration: Iteration): string | number | null | undefined => {
    return iteration.sha !== undefined ? iteration.sha : iteration.id
  }

  // Helper function to get the appropriate parent key for an iteration
  const getParentKey = (iteration: Iteration): string | number | null | undefined => {
    return iteration.parentSha !== undefined ? iteration.parentSha : iteration.parentId
  }

  const refinementMap = new Map(allRefinements.map(r => [r.id, r]))
  const refinementMapBySha = new Map(allRefinements.map(r => [r.sha, r]))

  // build lineage from active to root
  const orderedAllRefinements = [...allRefinements].reverse()
  const lineage: Iteration[] = []
  const visited = new Set<string | number>() // Prevent infinite loops

  for (let ptr: Iteration | undefined = activeRefinement; ptr; ) {
    const currentKey = getIterationKey(ptr)
    if (currentKey !== undefined && currentKey !== null && visited.has(currentKey)) {
      // Circular reference detected, break out
      break
    }
    if (currentKey !== undefined && currentKey !== null) {
      visited.add(currentKey)
    }
    lineage.push(ptr)
    const parentKey = getParentKey(ptr)
    // if parentKey is a SHA, we need to look it up in the map by SHA
    if (parentKey && typeof parentKey === 'string' && refinementMapBySha.has(parentKey)) {
      ptr = refinementMapBySha.get(parentKey)
    } else {
      // Otherwise, look it up by ID
      ptr = parentKey ? refinementMap.get(parentKey as number) : undefined
    }
  }
  const displayItems: DisplayItem[] = []

  let i = 0
  let j = 0
  for (; i < orderedAllRefinements.length; ) {
    const currRef = orderedAllRefinements[i]
    const currKey = currRef ? getIterationKey(currRef) : undefined
    const lineageKey = lineage[j] ? getIterationKey(lineage[j]!) : undefined

    if (currKey !== lineageKey && j === 0) {
      displayItems.push({type: 'refinement', refinement: currRef!})
      i++
    } else if (currKey === lineageKey) {
      displayItems.push({type: 'refinement', refinement: currRef!})
      i++
      j++
    } else {
      const skippedRefinements: Iteration[] = []
      const targetLineageKey = lineage[j] ? getIterationKey(lineage[j]!) : undefined

      for (
        ;
        i < orderedAllRefinements.length &&
        orderedAllRefinements[i] &&
        getIterationKey(orderedAllRefinements[i]!) !== targetLineageKey;
        i++
      ) {
        const ref = orderedAllRefinements[i]
        if (ref) skippedRefinements.push(ref)
      }
      if (skippedRefinements.length) {
        displayItems.push({type: 'skip', skippedRefinements: skippedRefinements.reverse()})
      }
    }
  }

  return displayItems.reverse()
}
