/*
 * Shown when user accounts have billing issues.
 */

import {Banner, Link} from '@primer/react'

import styles from './Banner.module.css'

export function CopilotBillingAssignmentBanner() {
  const description = (
    <>
      Before you can use GitHub Spark, you need to pick a &ldquo;Usage billed to&rdquo; option in your Copilot settings.{' '}
      <Link inline href="https://github.com/settings/copilot/features" target="_blank" rel="noopener noreferrer">
        Update your settings
      </Link>
      , then try again.
    </>
  )
  const title = 'Billing issue with your account.'
  const variant = 'critical'

  return <Banner className={styles.SparkBanner} description={description} hideTitle title={title} variant={variant} />
}
