import {resetFavicon, updateFaviconByVariant, type Variants} from '@github-ui/favicon'
import {useCallback, useEffect, useRef} from 'react'

import {AgentStatus, useAgentStatus} from '../contexts/WorkbenchStoreContext'

const RESET_TIMEOUT = 15000

export function SparkStatusFavicon() {
  const {isAgentBusy, status: agentStatus} = useAgentStatus()
  const timeoutIdRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  const faviconIsPendingRef = useRef(false)

  const startGeneration = useCallback(() => {
    updateFaviconByVariant('pending')
    faviconIsPendingRef.current = true
  }, [])

  const stopGeneration = useCallback((status: Variants) => {
    updateFaviconByVariant(status)
    faviconIsPendingRef.current = false
    clearTimeout(timeoutIdRef.current)
    timeoutIdRef.current = setTimeout(() => {
      resetFavicon()
    }, RESET_TIMEOUT)
  }, [])

  useEffect(() => {
    if (isAgentBusy) {
      startGeneration()
    } else if (faviconIsPendingRef.current && agentStatus === AgentStatus.CONNECTED) {
      stopGeneration('success')
    } else if (faviconIsPendingRef.current && agentStatus === AgentStatus.ERROR) {
      stopGeneration('failure')
    } else {
      resetFavicon()
    }

    return () => clearTimeout(timeoutIdRef.current)
  }, [agentStatus, isAgentBusy, startGeneration, stopGeneration])

  // This component renders nothing, it just updates the favicon
  return null
}
