import {useTheme} from '@primer/styled-react'
import {clsx} from 'clsx'
import React, {useEffect, useRef} from 'react'

import {Canvas2DRenderer} from './components/Canvas2DRenderer/Canvas2DRenderer'
import {LoadingMessages} from './components/LoadingMessages/LoadingMessages'
import {WebGLRenderer} from './components/WebGLRenderer/WebGLRenderer'
import {useWebGLSupport} from './hooks/use-webgl-support'
// import { Canvas2DCanvas } from "./Canvas2DRenderer";
import styles from './LoadingParticles.module.css'

interface LoadingParticlesProps {
  className?: string
}

export const LoadingParticles = ({className}: LoadingParticlesProps) => {
  const {status} = useWebGLSupport()

  const {colorScheme} = useTheme()
  const themeMode = ['dark', 'night'].some(mode => colorScheme?.includes(mode)) ? 'dark' : 'light'

  const [containerSize, setContainerSize] = React.useState({
    width: 0,
    height: 0,
  })

  const containerRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const updateContainerSize = () => {
      if (containerRef.current) {
        const {width, height} = containerRef.current.getBoundingClientRect()
        setContainerSize({width, height})
      }
    }

    updateContainerSize()

    const resizeObserver = new ResizeObserver(updateContainerSize)
    if (containerRef.current) {
      resizeObserver.observe(containerRef.current)
    }

    return () => {
      resizeObserver.disconnect()
    }
  }, [])

  return (
    <div ref={containerRef} className={clsx(styles.container, className)}>
      <LoadingMessages />
      {status === 'checking' ? null : status === 'supported' ? (
        <WebGLRenderer
          className={styles.canvas}
          width={containerSize.width}
          height={containerSize.height}
          themeMode={themeMode}
        />
      ) : (
        <Canvas2DRenderer
          className={styles.canvas}
          width={containerSize.width}
          height={containerSize.height}
          themeMode={themeMode}
        />
      )}
    </div>
  )
}
