import {type BrowserVersion, isSafariTooOldForCHIPS} from '../../utilities/browser-version'
import styles from './CookieBanner.module.css'

/**
 * Cookie banner content we show when the browser is not Safari itself on
 * the iOS platform. We need this because:
 *
 * 1. All browsers on iOS are WebKit wrappers so all of them share
 *    the same CHIPS-related issue.
 * 2. There is the "allow cross-site tracking" setting in Safari on iOS
 *    that users can use to unblock themselves, but it is applied only
 *    to Safari itself, but not the wrappers, so the live preview isn't
 *    functional in all other browsers besides the Safari.
 */
function NonSafariOnIos({websiteUrl}: {websiteUrl: string | null}) {
  return (
    <div className={styles.container}>
      <h2 className={styles.title}>⚠️ Unsupported Browser</h2>

      <div className={styles.content}>
        <section>
          <h3 className={styles.sectionTitle}>
            Inline live preview on iOS is currently supported only in Safari browser.
          </h3>
          {websiteUrl && (
            <p>
              You can still preview your Spark in another tab by{' '}
              <a href={websiteUrl} className={styles.link} target="_blank" rel="noopener noreferrer">
                clicking here.
              </a>
            </p>
          )}
        </section>
      </div>
    </div>
  )
}

export function CookieBanner({
  browserVersion,
  websiteUrl,
  hideCookieBanner,
}: {
  browserVersion: BrowserVersion
  websiteUrl: string | null
  hideCookieBanner: () => void
}) {
  // the live preview always is not functional in all iOS browsers besides Safari
  // see description of the {@link NonSafariOnIos} component for details
  if (browserVersion.isSafari === false && browserVersion.isIos) {
    return <NonSafariOnIos websiteUrl={websiteUrl} />
  }

  const needsUpgrade = isSafariTooOldForCHIPS(browserVersion)
  return (
    <div className={styles.container}>
      <h2 className={styles.title}>⚠️ Cookie Support Required for App Preview</h2>

      <div className={styles.content}>
        <section>
          <h3 className={styles.sectionTitle}>Problems with Safari</h3>
          <p>
            The latest version of Safari (18.5+) has{' '}
            <a
              href="https://bugs.webkit.org/show_bug.cgi?id=292975"
              className={styles.link}
              target="_blank"
              rel="noopener noreferrer"
            >
              a bug
            </a>{' '}
            preventing us from displaying embedded previews in Spark, which require partitioned cookie support to
            function properly.
          </p>

          {needsUpgrade && (
            <p>
              Versions of Safari older than 18.4 will require that you{' '}
              <a
                href="https://gh.io/apple-support-upgrade-safari"
                className={styles.link}
                target="_blank"
                rel="noopener noreferrer"
              >
                upgrade your Safari browser
              </a>{' '}
              once the above issue is fixed. An upgrade currently won&apos;t unlock embedded previews, however we do
              encourage you to stay current on your browser versions.
            </p>
          )}
        </section>

        <section>
          <h3 className={styles.sectionTitle}>Alternative Solutions</h3>
          {websiteUrl && (
            <p>
              You can view preview for your Spark in another tab or window by{' '}
              <a href={websiteUrl} className={styles.link} target="_blank" rel="noopener noreferrer">
                clicking here.
              </a>
            </p>
          )}
          <p>
            If you cannot upgrade your browser, you can enable third-party cookies in your current Safari version.{' '}
            <a
              href="https://gh.io/apple-support-prevent-cross-site-tracking-safari"
              className={styles.link}
              target="_blank"
              rel="noopener noreferrer"
            >
              Learn why this option is not preferred
            </a>
          </p>
          <div className={styles.instructions}>
            <h4 className={styles.sectionTitle}>Instructions:</h4>
            <ol className={styles.orderedList}>
              <li>Open Safari {'>'} Settings...</li>
              <li>
                Turn off the following settings:
                <ul className={styles.unorderedList}>
                  <li>Advanced {'>'} Block all cookies</li>
                  <li>Privacy {'>'} Prevent cross-site tracking</li>
                </ul>
              </li>
            </ol>
          </div>
        </section>

        <div className={styles.checkboxWrapper}>
          <label className={styles.checkboxLabel}>
            <input type="checkbox" onChange={() => hideCookieBanner()} className={styles.checkbox} />
            <span>I have enabled third-party cookies</span>
          </label>
        </div>
      </div>
    </div>
  )
}
