// eslint-disable-next-line no-restricted-imports
import {ScreenSize, useScreenSize} from '@github-ui/screen-size'
import {SyncIcon} from '@primer/octicons-react'
import {ActionList, IconButton} from '@primer/react'
import {clsx} from 'clsx'
import {memo, useMemo, useState} from 'react'

import {strings} from '../../constants'
import {useCodespaceContext} from '../../contexts/CodespaceContext'
import {useAgentStatus} from '../../contexts/WorkbenchStoreContext'
import {useWorkbenchUI} from '../../contexts/WorkbenchUIContext'
import styles from './Header.module.css'

export const RefreshPreview = memo(function RefreshPreviewButton({
  className,
  variant,
}: {
  className?: string
  variant: 'menu' | 'icon'
}) {
  const {isAgentBusy} = useAgentStatus()
  const {refreshPreview, workingMode} = useWorkbenchUI()
  const {screenSize} = useScreenSize()
  const {codespaceData} = useCodespaceContext()

  const [previewRefreshing, setPreviewRefreshing] = useState(false)

  const isLargeScreen = screenSize >= ScreenSize.large
  const isReady = codespaceData?.codespaceState === 'ready'
  const loading = !isReady || previewRefreshing
  const isAbleToRefreshPreview = !loading && !isAgentBusy && workingMode !== 'code'

  const handleRefreshPreview = () => {
    if (!isAbleToRefreshPreview) return
    setPreviewRefreshing(true)
    refreshPreview()
    // match duration in Header.module.css .spin class
    setTimeout(() => setPreviewRefreshing(false), 400)
  }

  const inactiveDescription = useMemo(() => {
    if (workingMode === 'code') return strings.ACTION_UNAVAILABLE_MODE
    if (isAgentBusy) return strings.ACTION_UNAVAILABLE_ITERATION
    return undefined
  }, [workingMode, isAgentBusy])

  return variant === 'menu' ? (
    <ActionList.Item
      aria-label="Refresh preview"
      className={className}
      hidden={isLargeScreen}
      onSelect={handleRefreshPreview}
      loading={loading}
      inactiveText={inactiveDescription}
    >
      <ActionList.LeadingVisual>
        <SyncIcon />
      </ActionList.LeadingVisual>
      Refresh preview
    </ActionList.Item>
  ) : (
    <IconButton
      icon={props => <SyncIcon {...props} className={previewRefreshing ? styles.spin : ''} />}
      aria-label="Refresh preview"
      className={clsx(styles.refreshButton, 'hide-sm hide-md', className)}
      onClick={() => {
        if (!isAbleToRefreshPreview) return
        handleRefreshPreview()
      }}
      inactive={!isAbleToRefreshPreview}
      description={inactiveDescription ? inactiveDescription : loading ? strings.ACTION_LOADING : undefined}
    />
  )
})
