import type {RemoteProvider} from '@github/codespaces-ssh-tunneling'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {useWorkspaceEditorUIDispatch} from '@github-ui/workspace-editor/contexts/WorkspaceEditorUIContext'
import {TunnelProtocol} from '@microsoft/dev-tunnels-contracts'
import {JSONRPCClient, JSONRPCServer, JSONRPCServerAndClient, type TypedJSONRPCServerAndClient} from 'json-rpc-2.0'
import {type PropsWithChildren, useCallback, useEffect, useMemo, useRef, useState} from 'react'

import {AggregateError} from '../../errors/aggregate-error'
import {codespaceInfoForTelemetry} from '../../hooks/use-codespace-helpers'
import {useAnalytics} from '../../telemetry/use-analytics'
import type {
  ClientRpcMethods,
  FileChange,
  IFileSyncer,
  OurDuplex,
  ServerRpcMethods,
} from '../../types/file-syncer-v2-types'
import type {FileDescription} from '../../types/spark-history-types'
import type {WorkbenchRoutePayload} from '../../types/workbench-types'
import workbenchConsole from '../../utilities/console'
import {withRetries} from '../../utilities/with-retries'
import {BannerType} from '../../utilities/workspace-editor-types'
import {useCodespaceContext} from '../CodespaceContext'
import {Service, useWorkbenchStore} from '../WorkbenchStoreContext'
import {AzureBlobFileSyncerClient} from './AzureBlobFileSyncerClient'
import {CodespaceFileSyncerClient} from './CodespaceFileSyncerClient'
import {FileSyncerContext} from './index'

type FileSyncerMode = 'blobStorage' | 'codespace'

export function FileSyncerContextProvider({children}: PropsWithChildren) {
  const {codespaceData: codespace} = useCodespaceContext()
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const sessionSnapshotEnabled = useFeatureFlag('copilot_workbench_session_snapshot')
  const {onConnected, onDisconnected} = useWorkbenchStore()
  const dispatch = useWorkspaceEditorUIDispatch()
  const sendEvent = useAnalytics()

  const [fileSyncerStarted, setFileSyncerStarted] = useState<boolean>(false)

  // These state variables are a little nuanced
  // contentStateStamp is used to communicate to the editor that it should re-render
  // fileTreeStateStamp is used for communicating overall file tree changes that should refresh
  // lastEditStateStamp notices file edits, but doesn't touch editor. It's for all other readers.
  const [contentStateStamp, setContentStateStamp] = useState(-1)
  const [fileTreeStateStamp, setFileTreeStateStamp] = useState(-1)
  const [lastEditStateStamp, setLastEditStateStamp] = useState(-1)
  const [fileChangeStack, setFileChangeStack] = useState<FileChange[]>([])
  const fileSyncerRef = useRef<IFileSyncer | null>(null)
  const fileContentsRef = useRef<{[key: string]: FileDescription} | null>(null)
  const abortControllerRef = useRef<AbortController | null>(null)

  const getFileSyncerV2 = useCallback(() => {
    return fileSyncerRef.current
  }, [fileSyncerRef])

  const setFileContentsRef = useCallback((files: {[key: string]: FileDescription} | null) => {
    fileContentsRef.current = files
  }, [])

  const [syncerMode, setSyncerMode] = useState<FileSyncerMode>(sessionSnapshotEnabled ? 'blobStorage' : 'codespace')

  const {snapshotUploadUri} = useRoutePayload<WorkbenchRoutePayload>()

  // Update a state property to force a re-render to the editor
  const forceContentRefresh = useCallback(() => {
    setContentStateStamp(Date.now())
  }, [])

  // Update a state property to force a re-render to the file tree
  const forceFileTreeRefresh = useCallback(() => {
    setFileTreeStateStamp(Date.now())
  }, [])

  // Update a state property to notify non-editor file readers of changes
  const notifyEdited = useCallback(() => {
    setLastEditStateStamp(Date.now())
  }, [])

  const disposeFileSyncer = useCallback(() => {
    fileSyncerRef.current?.dispose()
    fileSyncerRef.current = null
    setFileSyncerStarted(false)
    onDisconnected({service: Service.FILE_SYNCER})
  }, [onDisconnected])

  useEffect(() => {
    if (codespace?.codespaceState !== 'ready' && syncerMode === 'codespace' && fileSyncerStarted) {
      disposeFileSyncer()
      workbenchConsole.log('FileSyncerContext: Codespace disconnected, stopping file syncer')
    }
  }, [codespace?.codespaceState, disposeFileSyncer, fileSyncerStarted, onDisconnected, syncerMode])

  const startFileSyncer = useCallback(
    async (remoteProvider: RemoteProvider) => {
      // Abort any previous retry loop
      abortControllerRef.current?.abort()
      const abortController = new AbortController()
      abortControllerRef.current = abortController

      const newConnection = await withRetries(
        async () => {
          if (abortController.signal.aborted) {
            return null
          }
          return (await remoteProvider.getStreamFromPort(13000, TunnelProtocol.Http)) as OurDuplex
        },
        {
          retries: 12,
          retryDelayMs: 5000,
          shouldStopRetries: () => {
            if (abortController.signal.aborted) {
              workbenchConsole.log('FileSyncerContext: Aborting retries due to abort signal')
              return true
            }
            return false
          },
        },
      )

      if (abortController.signal.aborted && !newConnection) {
        workbenchConsole.log('FileSyncerContext: Aborted connection attempt - this is normal if a new attempt is made')
        throw new Error('FileSyncerContext: Connection attempt aborted - this is normal if a new attempt is made')
      }

      if (!newConnection) {
        workbenchConsole.log('FileSyncerContext: Failed to establish connection to file syncer')
        throw new Error('FileSyncerContext: Failed to establish connection to file syncer')
      } else {
        workbenchConsole.log('FileSyncerContext: Established connection to file syncer')
      }

      sendEvent('file_syncer.connection.success', {
        timestamp: new Date().toISOString(),
        ...codespaceInfoForTelemetry(codespace),
      })

      const client = new JSONRPCClient(request => {
        try {
          if (newConnection && newConnection.writable && !newConnection.destroyed && !newConnection.closed) {
            // Send the request to the server
            const requestMessage = `${JSON.stringify(request)}\n`
            newConnection.write(requestMessage)
            return Promise.resolve()
          } else {
            workbenchConsole.log('FileSyncer:: Connection is not writable, rejecting request')
            disposeFileSyncer()
            return Promise.reject(new Error('Connection is not writable'))
          }
        } catch (error) {
          return Promise.reject(error)
        }
      })

      const server = new JSONRPCServer()
      server.addMethod('notifyFileChanged', (rawChanges: FileChange[]) => {
        const changes: FileChange[] = rawChanges.map(change => {
          return {
            ...change,
            path: change.path.replace(/^\/workspaces\/[a-zA-Z0-9_-]+/, ''),
          } as FileChange
        })

        notifyEdited()
        forceFileTreeRefresh()
        setFileChangeStack(prevStack => {
          const newChanges = changes.filter(change => !prevStack.some(existing => existing.path === change.path))
          return [...prevStack, ...newChanges]
        })
      })

      const serverAndClient: TypedJSONRPCServerAndClient<ClientRpcMethods, ServerRpcMethods> =
        new JSONRPCServerAndClient(server, client)

      let buffer = ''
      newConnection.on('data', data => {
        // Guard against processing data after disposal or if connection is no longer valid
        if (newConnection.destroyed || newConnection.closed) {
          return
        }

        try {
          buffer += data.toString()
          // Split by newline and process each complete message
          const messages = buffer.split('\n')
          // Keep the last potentially incomplete message in the buffer
          buffer = messages.pop() || ''

          for (const message of messages) {
            if (message.trim()) {
              // Skip empty messages
              const jsonData = JSON.parse(message)
              serverAndClient.receiveAndSend(jsonData)
            }
          }
        } catch (error) {
          workbenchConsole.log(`FileSyncer:: Error processing data: ${error}`)
        }
      })

      // On close, make sure to reject all the pending requests to prevent hanging.
      newConnection.on('close', () => {
        workbenchConsole.log('FileSyncer Connection closed')
        serverAndClient.rejectAllPendingRequests('Connection is closed')
        disposeFileSyncer()
      })

      workbenchConsole.log('FileSyncerContext: FileSyncer client created and connected')

      const fileSyncer = new CodespaceFileSyncerClient(serverAndClient, newConnection)
      return fileSyncer
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [disposeFileSyncer],
  )

  useEffect(() => {
    if (fileSyncerStarted) {
      if (codespace?.codespaceState === 'ready' && syncerMode === 'codespace') return
      if (codespace?.codespaceState !== 'ready' && syncerMode === 'blobStorage') return
    }

    async function run() {
      if (syncerMode === 'blobStorage' && snapshotUploadUri && sessionSnapshotEnabled) {
        // Cut over to Codespaces file syncer if it's ready to use
        if (codespace?.codespaceState === 'ready') {
          await startCodespaceSyncerMode()
        } else {
          const blobSyncer = new AzureBlobFileSyncerClient(snapshotUploadUri)
          const hasContent = await blobSyncer.hasContent()
          if (!hasContent) {
            return
          }

          fileSyncerRef.current = blobSyncer
          setFileSyncerStarted(true)
          onConnected({service: Service.FILE_SYNCER})
        }
      } else if (!fileSyncerStarted && codespace?.codespaceState === 'ready') {
        await startCodespaceSyncerMode()
      }
    }

    async function startCodespaceSyncerMode() {
      if (codespace.remoteProvider) {
        try {
          fileSyncerRef.current = await startFileSyncer(codespace.remoteProvider)
          setSyncerMode('codespace')
          forceFileTreeRefresh()
          forceContentRefresh()
          setFileSyncerStarted(true)
          workbenchConsole.log('FileSyncerContext: Codespaces file syncer started')
          onConnected({service: Service.FILE_SYNCER})
        } catch (error) {
          if (error instanceof AggregateError) {
            workbenchConsole.log('FileSyncerContext: Error occurred while starting Codespace syncer - BANNER', error)
            sendEvent('file_syncer.connection_reload_banner.displayed', {
              timestamp: new Date().toISOString(),
              errorMessage: error?.message,
              ...codespaceInfoForTelemetry(codespace),
            })

            dispatch({type: 'SET_BANNER', banner: BannerType.CONNECTION_RELOAD})
          } else {
            workbenchConsole.log('FileSyncerContext: Error occurred while starting Codespace syncer - NO-BANNER', error)
            throw error
          }
        }
      }
    }

    run()
    // only keep the dependencies that are necessary forfile syncer connection
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    codespace?.codespaceState,
    codespace.remoteProvider,
    syncerMode,
    snapshotUploadUri,
    sessionSnapshotEnabled,
    fileSyncerStarted,
  ])

  const value = useMemo(() => {
    return {
      contentStateStamp,
      fileSyncerStarted,
      fileTreeStateStamp,
      lastEditStateStamp,
      notifyEdited,
      forceContentRefresh,
      forceFileTreeRefresh,
      getFileSyncerV2,
      syncerMode,
      setSyncerMode,
      fileContentsRef,
      fileChangeStack,
      setFileChangeStack,
      setFileContentsRef,
    }
  }, [
    contentStateStamp,
    fileSyncerStarted,
    fileTreeStateStamp,
    lastEditStateStamp,
    notifyEdited,
    forceContentRefresh,
    forceFileTreeRefresh,
    getFileSyncerV2,
    syncerMode,
    fileChangeStack,
    setFileChangeStack,
    setFileContentsRef,
  ])

  return <FileSyncerContext value={value}>{children}</FileSyncerContext>
}
