import {useEffect, useRef} from 'react'

import {SPARK_LIVE_PREVIEW_IFRAME_ID} from '../components/PreviewArea/Constants'

export function useSparkIframeFocus(callback: VoidFunction) {
  const callbackRef = useRef(callback)

  // update the callback reference to ensure the latest callback is used
  // this does not require consumer to remember to use useCallback and we can avoid stale closures
  useEffect(() => (callbackRef.current = callback), [callback])

  useEffect(() => {
    const handleBlur = () => {
      const iframePreview = document.getElementById(SPARK_LIVE_PREVIEW_IFRAME_ID)

      if (iframePreview && document.activeElement === iframePreview) {
        callbackRef.current()
      }
    }

    window.addEventListener('blur', handleBlur)

    return () => {
      window.removeEventListener('blur', handleBlur)
    }
  }, [])
}
