import {useCurrentUser} from '@github-ui/current-user'
import {ErrorBoundary} from '@github-ui/react-core/error-boundary'
import {useLocalStorage} from '@github-ui/use-safe-storage/local-storage'
import {
  useWorkspaceEditorUIDispatch,
  useWorkspaceEditorUIState,
} from '@github-ui/workspace-editor/contexts/WorkspaceEditorUIContext'
import {clsx} from 'clsx'
import {useCallback, useEffect, useMemo, useRef, useState} from 'react'

import {useCodespaceContext} from '../../contexts/CodespaceContext'
import {useErrors} from '../../contexts/ErrorsContext'
import {useIterationHistory} from '../../contexts/IterationHistoryContext'
import {useServerEvents} from '../../contexts/ServerEventsContext'
import {useWorkbenchPreview} from '../../contexts/WorkbenchPreviewContext'
import {useAgentStatus} from '../../contexts/WorkbenchStoreContext'
import {useWorkbenchUI} from '../../contexts/WorkbenchUIContext'
import {codespaceInfoForTelemetry, getUrlForPort} from '../../hooks/use-codespace-helpers'
import {useAnalytics} from '../../telemetry/use-analytics'
import {getBrowserVersion, isProblematicSafariVersion} from '../../utilities/browser-version'
import workbenchConsole from '../../utilities/console'
import {BannerType} from '../../utilities/workspace-editor-types'
import {LoadingParticles} from '../LoadingParticles/LoadingParticles'
import {CachedPreviewIframe} from './CachedPreviewIframe'
import {SPARK_PREVIEW_CONTAINER_ID} from './Constants'
import {CookieBanner} from './CookieBanner'
import {ErrorOverlay} from './ErrorOverlay'
import {LivePreviewIframe} from './LivePreviewIframe'
import styles from './PreviewArea.module.css'
import {PreviewOverlay} from './PreviewOverlay'
import {StaticPreviewIframe} from './StaticPreviewIframe'
import {type PreviewState, StatusPill} from './StatusPill'

// Iframe type constants
type IframeType = 'live' | 'cached' | 'static'

export const PreviewAreaV2 = () => {
  // Hooks
  const sendEvent = useAnalytics()
  const currentUser = useCurrentUser()
  const {codespaceData} = useCodespaceContext()
  const {mobileViewActive, refreshPreview} = useWorkbenchUI()
  const {isAgentBusy} = useAgentStatus()
  const {rehydrateCompleted, agentLifeCycle, setAgentLifeCycle} = useServerEvents()
  const {state} = useWorkbenchPreview()
  const {overlayErrors} = useErrors()
  const browserVersion = getBrowserVersion()
  const isProblematicSafari = isProblematicSafariVersion(browserVersion)
  const dispatch = useWorkspaceEditorUIDispatch()
  const {banner} = useWorkspaceEditorUIState()
  const {onIFrameLoaded} = useWorkbenchPreview()

  // States
  const [iframeToShow, setIframeToShow] = useState<IframeType | null>(null)
  const [nextIframeToShow, setNextIframeToShow] = useState<IframeType | null>(null)
  const [loadedIframes, setLoadedIframes] = useState<{
    live: boolean
    static: boolean
    cached: boolean
  }>({
    live: false,
    static: false,
    cached: false,
  })
  const [liveIframeInitialLoad, setLiveIframeInitialLoad] = useState(false)
  const [previewState, setPreviewState] = useState<PreviewState>('loading')
  const [startRootElementEmptyTimeout, setStartRootElementEmptyTimeout] = useState(false)
  const [rehydrateCheckTimedOut, setRehydrateCheckTimedOut] = useState(false)
  const [canShowStaticPreview, setCanShowStaticPreview] = useState(true)
  const {isInitialIteration} = useIterationHistory()

  // Variables
  const initialLoadTime = useMemo(() => performance.now(), [])
  const codespaceName = codespaceData?.codespaceInfo?.environment_data.friendlyName
  const shouldBlockPreview = isAgentBusy && agentLifeCycle !== 'showPreviewRequested'

  // Banners
  const [cookieBannerOverride, setCookieBannerOverride] = useLocalStorage<boolean>(
    'spark:cookie-banner-override',
    !isProblematicSafari,
  )
  const [showCookieBanner, setShowCookieBanner] = useState(isProblematicSafari && !cookieBannerOverride)
  const hideCookieBanner = useCallback(() => {
    setCookieBannerOverride(true)
    setShowCookieBanner(false)
  }, [setCookieBannerOverride])

  const showConnectionReloadBanner = useCallback(() => {
    if (state.viteWsConnected || showCookieBanner) return
    sendEvent('preview.connection_reload_banner.displayed', {
      timestamp: new Date().toISOString(),
      rootElementEmpty: state.rootElementEmpty,
      viteServerReady: state.viteServerReady,
      viteWsConnected: state.viteWsConnected,
      v2: true,
      ...codespaceInfoForTelemetry(codespaceData),
    })

    dispatch({type: 'SET_BANNER', banner: BannerType.CONNECTION_RELOAD})
  }, [
    codespaceData,
    dispatch,
    sendEvent,
    showCookieBanner,
    state.rootElementEmpty,
    state.viteServerReady,
    state.viteWsConnected,
  ])

  const hideConnectionReloadBanner = useCallback(() => {
    if (banner !== BannerType.CONNECTION_RELOAD) return
    dispatch({type: 'SET_BANNER', banner: undefined})
  }, [banner, dispatch])

  const checkRehydrateEventTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  useEffect(() => {
    if (!rehydrateCompleted && codespaceData?.codespaceState === 'ready') {
      if (!checkRehydrateEventTimerRef.current) {
        checkRehydrateEventTimerRef.current = setTimeout(() => {
          setRehydrateCheckTimedOut(true)
          checkRehydrateEventTimerRef.current = null
        }, 30000)
      }
    }
    return () => {
      if (checkRehydrateEventTimerRef.current) {
        clearTimeout(checkRehydrateEventTimerRef.current)
        checkRehydrateEventTimerRef.current = null
      }
    }
  }, [rehydrateCompleted, codespaceData?.codespaceState])

  const setPreviewReady = useCallback(() => {
    if (shouldBlockPreview) return
    if (!liveIframeInitialLoad) {
      setLiveIframeInitialLoad(true)

      // calculate the elapsed time since the codespace became ready
      const elapsedTime =
        codespaceData.readyTimestamp !== undefined ? performance.now() - codespaceData.readyTimestamp : -1

      workbenchConsole.log(`Live preview loaded duration ${elapsedTime.toFixed(2)}ms`)
      sendEvent('preview.ready.success', {
        duration: elapsedTime,
        v2: true,
      })
    }

    setPreviewState('ready')
    setNextIframeToShow('live')
  }, [shouldBlockPreview, liveIframeInitialLoad, sendEvent, codespaceData.readyTimestamp])

  useEffect(() => {
    if (
      codespaceData?.codespaceState === 'ready' &&
      state.viteWsConnected &&
      (rehydrateCompleted || rehydrateCheckTimedOut || !state.rootElementEmpty)
    ) {
      if (!rehydrateCompleted) {
        workbenchConsole.log('Rehydrate event not received, continuing anyways')
      }

      // Check page has loaded content
      if (state.rootElementEmpty) {
        setStartRootElementEmptyTimeout(true)
      } else {
        setPreviewReady()
      }
    }
  }, [
    codespaceData?.codespaceState,
    state.viteWsConnected,
    rehydrateCompleted,
    state.rootElementEmpty,
    setPreviewReady,
    rehydrateCheckTimedOut,
  ])

  const rootElementEmptyTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  useEffect(() => {
    if (startRootElementEmptyTimeout && !rootElementEmptyTimerRef.current) {
      rootElementEmptyTimerRef.current = setTimeout(() => {
        setPreviewReady()
        rootElementEmptyTimerRef.current = null
        setStartRootElementEmptyTimeout(false)
      }, 3000)
    }
    return () => {
      if (rootElementEmptyTimerRef.current) {
        clearTimeout(rootElementEmptyTimerRef.current)
        rootElementEmptyTimerRef.current = null
      }
    }
  }, [setPreviewReady, startRootElementEmptyTimeout])

  useEffect(() => {
    let timeoutId: NodeJS.Timeout | null = null
    if (nextIframeToShow && loadedIframes[nextIframeToShow]) {
      timeoutId = setTimeout(() => {
        if (nextIframeToShow === 'cached') {
          setPreviewState('loading')
        }
        setIframeToShow(nextIframeToShow)
        setNextIframeToShow(null)
      }, 1000) // Delay to allow the iframe to fully load before switching, to avoid flashing
    }

    return () => {
      if (timeoutId) {
        clearTimeout(timeoutId)
        timeoutId = null
      }
    }
  }, [loadedIframes, nextIframeToShow])

  const handleIframeLoaded = useCallback(
    (iframeName: IframeType, event: React.SyntheticEvent<HTMLIFrameElement>) => {
      setLoadedIframes(prev => ({...prev, [iframeName]: true}))
      if (iframeName === 'live') {
        onIFrameLoaded(event)
      }
    },
    [onIFrameLoaded],
  )

  const previewOverlayForFetching = shouldBlockPreview && (isInitialIteration || !canShowStaticPreview)
  const showPreviewOverlay = !showCookieBanner && (!iframeToShow || previewOverlayForFetching)

  // Monitor viteWsConnected and show connection reload banner if disconnected for more than 5 seconds
  useEffect(() => {
    let delayTimeoutId: NodeJS.Timeout | null = null
    async function delay(ms: number = 2000) {
      await new Promise(resolve => {
        if (delayTimeoutId) clearTimeout(delayTimeoutId)
        delayTimeoutId = setTimeout(resolve, ms)
      })
    }

    if (isAgentBusy || !state.viteServerReady || !loadedIframes.live) {
      hideConnectionReloadBanner()
      return
    }

    if (!state.viteWsConnected) {
      tryReconnectToViteWs()
    } else {
      hideConnectionReloadBanner()
    }

    async function tryReconnectToViteWs() {
      await delay(5000) // Wait 5 seconds to allow auto reconnection

      refreshPreview()
      await delay(3000) // Wait for 3 seconds to allow the iframe to reload

      showConnectionReloadBanner()
    }

    return () => {
      if (delayTimeoutId) clearTimeout(delayTimeoutId)
    }
  }, [
    state.viteWsConnected,
    showConnectionReloadBanner,
    hideConnectionReloadBanner,
    isAgentBusy,
    refreshPreview,
    state.viteServerReady,
    loadedIframes.live,
  ])

  useEffect(() => {
    if (state.viteServerReady) {
      // calculate the elapsed time since the codespace became ready
      const viteServerReady =
        codespaceData.readyTimestamp !== undefined ? performance.now() - codespaceData.readyTimestamp : -1

      workbenchConsole.log(`viteServerReady duration ${viteServerReady.toFixed(2)}ms`)
      sendEvent('preview.viteServerReady.success', {
        duration: viteServerReady,
        v2: true,
      })
    }
    // the `sendEvent()` function always changes so we don't want to include it into the dependencies list
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state.viteServerReady, codespaceData.readyTimestamp])

  useEffect(() => {
    if (state.viteWsConnected) {
      // calculate the elapsed time since the codespace became ready
      const viteWsConnected =
        codespaceData.readyTimestamp !== undefined ? performance.now() - codespaceData.readyTimestamp : -1

      workbenchConsole.log(`viteWsConnected duration ${viteWsConnected.toFixed(2)}ms`)
      sendEvent('preview.viteWsConnected.success', {
        duration: viteWsConnected,
        v2: true,
      })
    }
    // the `sendEvent()` function always changes so we don't want to include it into the dependencies list
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state.viteWsConnected, codespaceData.readyTimestamp])

  useEffect(() => {
    if (rehydrateCompleted) {
      const rehydrateDuration =
        codespaceData.readyTimestamp !== undefined ? performance.now() - codespaceData.readyTimestamp : -1

      workbenchConsole.log(`rehydrate duration ${rehydrateDuration.toFixed(2)}ms`)
      sendEvent('preview.rehydrate.success', {
        duration: rehydrateDuration,
        v2: true,
      })
    }
    // the `sendEvent()` function always changes so we don't want to include it into the dependencies list
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [rehydrateCompleted, codespaceData.readyTimestamp])

  // Send Telemetry when Values Change
  useEffect(
    () => {
      sendEvent('preview.info', {
        isFetching: isAgentBusy,
        showCookieBanner,
        rootElementEmpty: state.rootElementEmpty,
        rootElementExists: state.rootElementExists,
        viteServerReady: state.viteServerReady,
        viteWsConnected: state.viteWsConnected,
        viteUpdated: state.viteUpdated,
        viteError: state.viteError,
        viteSessionId: state.viteSessionId,
        codespaceNamePresent: codespaceName !== undefined,
        showPreviewOverlay,
        readOnlyState: iframeToShow === 'cached',
        overlayErrors: overlayErrors?.length || 0,
        iframeToShow,
        v2: true,
        ...codespaceInfoForTelemetry(codespaceData),
        timestamp: new Date().toISOString(),
      })
      if (currentUser?.isStaff) {
        workbenchConsole.log(`Empty app handling conditions:
        isAgentBusy: ${isAgentBusy}
        viteServerReady: ${state.viteServerReady}
        viteWsConnected: ${state.viteWsConnected}
        viteUpdated: ${state.viteUpdated}
        viteError: ${state.viteError}
        viteSessionId: ${state.viteSessionId}
        rootElementEmpty: ${state.rootElementEmpty}
        rootElementExists: ${state.rootElementExists}
        rehydrateCompleted: ${rehydrateCompleted}
        readOnlyMode: ${iframeToShow === 'cached'}
        overlayErrors: ${overlayErrors?.length || 0}
        iframeToShow: ${iframeToShow}
        agentLifeCycle: ${agentLifeCycle}
      `)
      }
    },
    // the `sendEvent()` function always changes so we don't want to include it into the dependencies list
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [
      codespaceName,
      isAgentBusy,
      showCookieBanner,
      showPreviewOverlay,
      state.rootElementEmpty,
      state.viteServerReady,
      state.viteWsConnected,
      codespaceData,
      rehydrateCompleted,
      overlayErrors?.length,
      iframeToShow,
      agentLifeCycle,
    ],
  )

  const isAgentBusyRef = useRef(isAgentBusy)

  // Clear any runtime errors that may have been created during iteration
  useEffect(() => {
    const wasFetching = isAgentBusyRef.current
    isAgentBusyRef.current = isAgentBusy

    // If the agent requests to show preview while fetching, refresh the preview
    if (isAgentBusy && agentLifeCycle === 'showPreviewRequested') {
      refreshPreview()
    } else if (!isAgentBusy && wasFetching) {
      // Refresh preview when fetching completes if there was no 'showPreviewRequested'
      if (agentLifeCycle !== 'showPreviewRequested') {
        refreshPreview()
      }

      setAgentLifeCycle('idle')
    }
  }, [isAgentBusy, agentLifeCycle, refreshPreview, setAgentLifeCycle])

  const showCachedIframe = useCallback(() => {
    setIframeToShow('cached')
    setPreviewState('loading')
  }, [])

  // On reconnections when live iframe is unloaded, switch to cached preview if available
  useEffect(() => {
    if (iframeToShow === 'live' && !loadedIframes['live']) {
      if (loadedIframes['cached']) {
        showCachedIframe()
      } else {
        setIframeToShow(null)
      }
    }
  }, [iframeToShow, loadedIframes, showCachedIframe])

  const iframes = useMemo(() => {
    return (
      <>
        <CachedPreviewIframe
          show={iframeToShow === 'cached'}
          onLoad={(event: React.SyntheticEvent<HTMLIFrameElement>) => {
            handleIframeLoaded('cached', event)
            showCachedIframe()

            const readonlyPreviewLoadTime = (performance.now() - initialLoadTime).toFixed(2)
            workbenchConsole.log(`Cached url loaded duration ${readonlyPreviewLoadTime}ms`)
            sendEvent('preview.cached.url.loaded', {
              duration: readonlyPreviewLoadTime,
              v2: true,
            })
          }}
        />
        <LivePreviewIframe
          show={iframeToShow === 'live'}
          onLoad={(event: React.SyntheticEvent<HTMLIFrameElement>, empty: boolean) => {
            if (empty) {
              setLoadedIframes(prev => ({...prev, live: false}))
            } else {
              handleIframeLoaded('live', event)
            }
          }}
        />
        <StaticPreviewIframe
          show={iframeToShow === 'static'}
          onPreviewAvailableChange={available => {
            setCanShowStaticPreview(available)
          }}
          onReady={() => {
            setNextIframeToShow('static')
          }}
          onLoad={(event: React.SyntheticEvent<HTMLIFrameElement>, empty: boolean) => {
            if (empty) {
              setLoadedIframes(prev => ({...prev, static: false}))
            } else {
              handleIframeLoaded('static', event)
            }
          }}
        />
      </>
    )
  }, [iframeToShow, handleIframeLoaded, showCachedIframe, initialLoadTime, sendEvent])

  return (
    <div
      id={SPARK_PREVIEW_CONTAINER_ID}
      className={clsx(styles.previewContainer, mobileViewActive && styles.previewContainerMobileBackground)}
    >
      {!showPreviewOverlay && <StatusPill state={previewState} />}
      <div className={styles.iframeWrapper}>
        <div className={mobileViewActive ? styles.mobileFrame : undefined}>{iframes}</div>
      </div>
      <ErrorBoundary fallback={<PreviewOverlay isLoading={showPreviewOverlay} />}>
        {showPreviewOverlay ? <LoadingParticles /> : null}
      </ErrorBoundary>
      <ErrorOverlay />
      {showCookieBanner && (
        <CookieBanner
          browserVersion={browserVersion}
          websiteUrl={getUrlForPort(codespaceData, '5000')}
          hideCookieBanner={hideCookieBanner}
        />
      )}
    </div>
  )
}
