import {LinkExternalIcon} from '@primer/octicons-react'
import {Button, Dialog, FormControl, Link, LinkButton} from '@primer/react'
import {type FormEvent, useId, useRef, useState} from 'react'

import {useWorkbenchContext} from '../contexts/WorkbenchContext'
import type {RepositoryVisibility} from '../hooks/use-workbench'

interface CreateRepositoryDialogProps {
  ownerLogin: string
  name: string
  onCancel: () => void
  onSubmit: (name: string, visibility: RepositoryVisibility) => Promise<void>
}

const CreateRepositoryDialog = ({ownerLogin, name, onCancel, onSubmit}: CreateRepositoryDialogProps) => {
  const {repositoryUrl} = useWorkbenchContext()

  const [status, setStatus] = useState<'not-created' | 'creating' | 'created'>('not-created')
  const [error, setError] = useState<Error | null>(null)

  const inputRef = useRef<HTMLInputElement>(null)
  const formId = useId()

  // Repository is created when we have a URL or when creation completed successfully
  const isRepositoryCreated = status === 'created' || Boolean(repositoryUrl)

  const submit = async (event: FormEvent) => {
    event.preventDefault()

    setStatus('creating')
    setError(null)

    // TODO: actually let the user choose repo visibility
    try {
      await onSubmit(name, 'private')
      setStatus('created')
    } catch (err) {
      setStatus('not-created')
      if (err instanceof Error) {
        setError(err)
      } else {
        throw err
      }
    }
  }

  const handleClose = () => {
    onCancel()
  }

  const nwo = `${ownerLogin}/${name}`

  return (
    <Dialog
      title={isRepositoryCreated ? 'Repository created' : 'Create repository'}
      onClose={handleClose}
      width="large"
      initialFocusRef={inputRef}
      renderFooter={() => {
        return (
          <Dialog.Footer>
            <Button disabled={status === 'creating'} onClick={handleClose}>
              {isRepositoryCreated ? 'Close' : 'Cancel'}
            </Button>
            {repositoryUrl ? (
              <LinkButton
                trailingVisual={LinkExternalIcon}
                as="a"
                href={repositoryUrl}
                variant="primary"
                target="_blank"
              >
                Go to repository
              </LinkButton>
            ) : (
              <Button
                type="submit"
                variant="primary"
                form={formId}
                inactive={status === 'creating'}
                loading={status === 'creating'}
              >
                Create
              </Button>
            )}
          </Dialog.Footer>
        )
      }}
    >
      <form id={formId} onSubmit={submit}>
        <FormControl>
          <FormControl.Label visuallyHidden>Repository Information</FormControl.Label>
          {isRepositoryCreated && repositoryUrl ? (
            <span>
              {`Your spark's code is available in a private repository at: `}
              <Link href={repositoryUrl} inline target="_blank">
                {repositoryUrl}
              </Link>
            </span>
          ) : isRepositoryCreated ? (
            <span>
              Repository <span className="text-bold">{nwo}</span> has been created successfully.
            </span>
          ) : (
            <span>
              {`Your spark's code will be available in a private repository created as: `}
              <span className="text-bold">{nwo}</span>
            </span>
          )}
          {error && <FormControl.Validation variant="error">{error.message}</FormControl.Validation>}
        </FormControl>
      </form>
    </Dialog>
  )
}

export default CreateRepositoryDialog
