import {useEffect, useRef} from 'react'

import type {Point2D} from '../types'

interface TouchData {
  x: number
  y: number
  lastX: number
  lastY: number
  startX: number
  startY: number
  hasMoved: boolean
  isFirstMove: boolean
}

/**
 * Helper function to get pointer position from event
 */
const getPointerPosition = (
  event: globalThis.MouseEvent | globalThis.TouchEvent,
  canvas: HTMLCanvasElement,
): Point2D => {
  const rect = canvas.getBoundingClientRect()

  // Handle both mouse and touch events
  let clientX: number
  let clientY: number

  if ('touches' in event && event.touches.length > 0) {
    // Touch event - use first touch
    clientX = event.touches[0]!.clientX
    clientY = event.touches[0]!.clientY
  } else if ('changedTouches' in event && event.changedTouches.length > 0) {
    // Touch end event - use first changed touch
    clientX = event.changedTouches[0]!.clientX
    clientY = event.changedTouches[0]!.clientY
  } else {
    // Mouse event
    const mouseEvent = event as globalThis.MouseEvent
    clientX = mouseEvent.clientX
    clientY = mouseEvent.clientY
  }

  return {
    x: clientX - rect.left,
    y: clientY - rect.top,
  }
}

interface PointerInteractionOptions {
  onApplyForce: (x: number, y: number, velocity: {x: number; y: number; speed: number}) => void
  onStartSpawning?: (x: number, y: number) => void
  onStopSpawning?: () => void
  onUpdateSpawnPosition?: (x: number, y: number) => void
}

/**
 * Custom hook for handling mouse and touch interactions with the particle system
 * This hook manages unified pointer input handling, velocity tracking, and multi-touch support
 */
export const usePointerInteraction = (
  canvasRef: React.RefObject<HTMLCanvasElement | null>,
  options: PointerInteractionOptions,
) => {
  const isSpawningRef = useRef<boolean>(false)
  // Mouse velocity tracking
  const lastMousePosRef = useRef<Point2D>({x: 0, y: 0})
  const mouseVelocityRef = useRef<{x: number; y: number; speed: number}>({
    x: 0,
    y: 0,
    speed: 0,
  })
  const isMouseInsideCanvasRef = useRef<boolean>(false)
  const optionsRef = useRef<PointerInteractionOptions>(options)

  useEffect(() => {
    optionsRef.current = options
  }, [options])

  // Track active touches for multi-touch support
  const activeTouchesRef = useRef<Map<number, TouchData>>(new Map())

  /**
   * Unified pointer move handler for both mouse and touch
   */

  /**
   * Set up all event listeners directly on the canvas element
   */
  useEffect(() => {
    const canvasElement = canvasRef.current
    if (!canvasElement) return

    // Capture the ref value to use in cleanup
    const activeTouches = activeTouchesRef.current

    const handlePointerMove = (event: globalThis.MouseEvent): void => {
      const position = getPointerPosition(event, canvasElement)
      const {x: pointerX, y: pointerY} = position

      // Only calculate velocity for mouse events, not touch events
      // Touch events handle their own velocity calculation
      if (event.type === 'mousemove') {
        // Only calculate velocity if mouse was already inside canvas
        if (isMouseInsideCanvasRef.current) {
          const lastPos = lastMousePosRef.current
          const velocityX = pointerX - lastPos.x
          const velocityY = pointerY - lastPos.y
          const speed = Math.sqrt(velocityX * velocityX + velocityY * velocityY)

          // Update velocity tracking
          mouseVelocityRef.current = {x: velocityX, y: velocityY, speed}
        } else {
          // Reset velocity when mouse first enters canvas
          mouseVelocityRef.current = {x: 0, y: 0, speed: 0}
          isMouseInsideCanvasRef.current = true
        }

        // Always update last position for next frame
        lastMousePosRef.current = {x: pointerX, y: pointerY}

        optionsRef.current.onApplyForce(pointerX, pointerY, mouseVelocityRef.current)

        if (isSpawningRef.current) {
          optionsRef.current.onUpdateSpawnPosition?.(pointerX, pointerY)
        }
      }
    }

    /**
     * Unified pointer down handler for both mouse and touch
     */
    const handlePointerDown = (event: globalThis.MouseEvent): void => {
      const position = getPointerPosition(event, canvasElement)
      const {x: pointerX, y: pointerY} = position

      // For mouse events, ensure we're tracking properly
      if (event.type === 'mousedown') {
        isMouseInsideCanvasRef.current = true
        lastMousePosRef.current = {x: pointerX, y: pointerY}
        mouseVelocityRef.current = {x: 0, y: 0, speed: 0}
      }

      isSpawningRef.current = true
      optionsRef.current.onStartSpawning?.(pointerX, pointerY)
    }

    /**
     * Unified pointer up handler for both mouse and touch
     */
    const handlePointerUp = (): void => {
      isSpawningRef.current = false
      optionsRef.current.onStopSpawning?.()
    }

    const handleMouseEnter = (): void => {
      // Reset velocity when mouse enters canvas to prevent large velocity jumps
      mouseVelocityRef.current = {x: 0, y: 0, speed: 0}
      isMouseInsideCanvasRef.current = false // Will be set to true on first move
    }

    const handleMouseLeave = (): void => {
      // Stop spawning when mouse leaves canvas
      if (isSpawningRef.current) {
        isSpawningRef.current = false
        optionsRef.current.onStopSpawning?.()
      }

      // Reset mouse tracking state
      isMouseInsideCanvasRef.current = false
      mouseVelocityRef.current = {x: 0, y: 0, speed: 0}
    }

    // Touch event handlers
    const handleTouchStart = (event: globalThis.TouchEvent): void => {
      // Handle all new touches
      for (let i = 0; i < event.changedTouches.length; i++) {
        const touch = event.changedTouches[i]!
        const rect = canvasElement.getBoundingClientRect()
        const touchX = touch.clientX - rect.left
        const touchY = touch.clientY - rect.top

        // Store touch data with initial velocity of zero
        activeTouchesRef.current.set(touch.identifier, {
          x: touchX,
          y: touchY,
          lastX: touchX,
          lastY: touchY,
          startX: touchX,
          startY: touchY,
          hasMoved: false,
          isFirstMove: true,
        })
      }

      // Check if we now have two or more fingers - start spawning at first finger's position
      if (activeTouchesRef.current.size >= 2) {
        const firstTouch = activeTouchesRef.current.values().next().value
        if (firstTouch) {
          isSpawningRef.current = true
          optionsRef.current.onStartSpawning?.(firstTouch.x, firstTouch.y)
        }
      } else {
        // Single finger - stop any existing spawning
        if (isSpawningRef.current) {
          isSpawningRef.current = false
          optionsRef.current.onStopSpawning?.()
        }
      }
    }

    const handleTouchMove = (event: globalThis.TouchEvent): void => {
      // Prevent default touch behavior (scrolling)
      event.preventDefault()

      const canvas = canvasRef.current
      if (!canvas) return

      const rect = canvas.getBoundingClientRect()

      // Handle all moving touches
      for (let i = 0; i < event.changedTouches.length; i++) {
        const touch = event.changedTouches[i]!
        const touchData = activeTouchesRef.current.get(touch.identifier)

        if (touchData) {
          const touchX = touch.clientX - rect.left
          const touchY = touch.clientY - rect.top

          // Check if this is actual movement (not just a tiny touch variation)
          const moveDistance = Math.sqrt(
            Math.pow(touchX - touchData.startX, 2) + Math.pow(touchY - touchData.startY, 2),
          )

          // Only start applying forces if touch has moved significantly (more than 5 pixels)
          const isSignificantMove = moveDistance > 5

          if (isSignificantMove) {
            touchData.hasMoved = true
          }

          // Calculate touch velocity for force application
          let velocity = {x: 0, y: 0, speed: 0}

          if (touchData.hasMoved && !touchData.isFirstMove) {
            const velocityX = touchX - touchData.lastX
            const velocityY = touchY - touchData.lastY
            const speed = Math.sqrt(velocityX * velocityX + velocityY * velocityY)
            velocity = {x: velocityX, y: velocityY, speed}

            // Apply force for this touch (works for both single and multi-touch)
            optionsRef.current.onApplyForce(touchX, touchY, velocity)
          }

          // Update stored touch data
          touchData.lastX = touchX
          touchData.lastY = touchY
          touchData.x = touchX
          touchData.y = touchY
          touchData.isFirstMove = false
        }
      }

      // Update spawn position if we have 2+ fingers (always use first finger's position)
      if (activeTouchesRef.current.size >= 2) {
        const firstTouch = activeTouchesRef.current.values().next().value
        if (firstTouch && isSpawningRef.current) {
          optionsRef.current.onUpdateSpawnPosition?.(firstTouch.x, firstTouch.y)
        }
      }
    }

    const handleTouchEnd = (event: globalThis.TouchEvent): void => {
      // Handle all ended touches
      for (let i = 0; i < event.changedTouches.length; i++) {
        const touch = event.changedTouches[i]!
        activeTouchesRef.current.delete(touch.identifier)
      }

      // Check touch count after removal
      if (activeTouchesRef.current.size >= 2) {
        // Still have 2+ fingers, keep spawning at first finger's position
        const firstTouch = activeTouchesRef.current.values().next().value
        if (firstTouch && isSpawningRef.current) {
          // Make sure spawning is still active at the first finger's position
          optionsRef.current.onUpdateSpawnPosition?.(firstTouch.x, firstTouch.y)
        }
      } else {
        // Less than 2 fingers remaining, stop spawning
        if (isSpawningRef.current) {
          isSpawningRef.current = false
          optionsRef.current.onStopSpawning?.()
        }
      }
    }

    const handleTouchCancel = (event: globalThis.TouchEvent): void => {
      handleTouchEnd(event)
    }

    // Add all event listeners to canvas
    canvasElement.addEventListener('mousemove', handlePointerMove)
    canvasElement.addEventListener('mousedown', handlePointerDown)
    canvasElement.addEventListener('mouseup', handlePointerUp)
    canvasElement.addEventListener('mouseenter', handleMouseEnter)
    canvasElement.addEventListener('mouseleave', handleMouseLeave)
    canvasElement.addEventListener('touchstart', handleTouchStart, {
      passive: true,
    })
    canvasElement.addEventListener('touchmove', handleTouchMove, {
      passive: true,
    })
    canvasElement.addEventListener('touchend', handleTouchEnd, {
      passive: true,
    })
    canvasElement.addEventListener('touchcancel', handleTouchCancel)

    // Cleanup function
    return () => {
      canvasElement.removeEventListener('mousemove', handlePointerMove)
      canvasElement.removeEventListener('mousedown', handlePointerDown)
      canvasElement.removeEventListener('mouseup', handlePointerUp)
      canvasElement.removeEventListener('mouseenter', handleMouseEnter)
      canvasElement.removeEventListener('mouseleave', handleMouseLeave)
      canvasElement.removeEventListener('touchstart', handleTouchStart)
      canvasElement.removeEventListener('touchmove', handleTouchMove)
      canvasElement.removeEventListener('touchend', handleTouchEnd)
      canvasElement.removeEventListener('touchcancel', handleTouchCancel)

      // Clear touch state using captured variable
      activeTouches.clear()
    }
  }, [canvasRef])
}
